package productui

func agentAnswerDocumentStyles() string {
	return `.docs-cited-version{min-width:0;overflow-wrap:anywhere}.docs-cited-version-notice,.docs-cited-version-state{display:flex;flex-wrap:wrap;align-items:center;gap:var(--hcm-space-2);padding:var(--hcm-space-3);border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);background:var(--hcm-color-brand-soft)}.docs-cited-version-notice p{flex:1 1 100%;margin:0}.docs-cited-section{background:var(--hcm-color-brand-soft);outline:var(--hcm-focus-ring-width) solid var(--hcm-color-focus);outline-offset:var(--hcm-space-1);scroll-margin-block-start:8rem}@media(prefers-reduced-motion:reduce){.docs-cited-version *{scroll-behavior:auto!important;animation:none!important;transition:none!important}}`
}
